#!/usr/bin/env python3
"""Builds the shipment summary described in /app/docs/summary-format.md."""
import csv
import datetime as dt
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_EVEN

UNIT_KG = {"kg": Decimal(1), "g": Decimal("0.001"),
           "lb": Decimal("0.45359237"), "oz": Decimal("0.028349523125")}
HANDOVER_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
COUNTED = {"delivered", "delivered_late"}
HARBOR_STATES = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}
# name: (record length, {field: (start, end)}) with 1-based inclusive columns
LAYOUTS = {
    "FW1": (42, dict(id=(1, 9), type=(10, 10), shipped=(11, 17), weight=(18, 25), status=(26, 26))),
    "FW2": (43, dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27))),
    "FW3": (41, dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25))),
}
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
}
DELIMS = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "river": "MM/DD/YYYY",
             "west": "DD.MM.YYYY", "harbor": "iso"}
BASE_UNIT = {"east": "kg", "lakeside": "kg", "river": "kg", "west": "kg", "harbor": "kg"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be")
    m = re.search(rb"^[ \t]*#[ \t]*charset[ \t]*[:=][ \t]*([A-Za-z0-9_.:-]+)", b[:2048], re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1).decode("ascii"))
        except (LookupError, UnicodeDecodeError):
            pass
    return b.decode("utf-8", errors="replace")


# ---------------------------------------------------------------- values
def id_number(s):
    m = re.search(r"[Ss][Hh]\D*(\d+)", s or "")
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def norm_unit(s):
    s = (s or "").strip().lower()
    return {"kgs": "kg", "kilogram": "kg", "kilograms": "kg", "gram": "g", "grams": "g",
            "lbs": "lb", "pound": "lb", "pounds": "lb", "ounce": "oz", "ounces": "oz"}.get(s, s)


def parse_number(s, decimal="."):
    s = s.strip().replace(" ", "").replace(" ", "")
    if decimal == ",":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


def parse_weight(text, default_unit, decimal=".", field_unit=None):
    """Returns kg as Decimal. Unit priority: written with value, field, default."""
    text = text.strip()
    m = re.match(r"^([-+]?[\d.,\s]*\d)\s*([A-Za-z]+)?$", text)
    if not m:
        raise ValueError("bad weight %r" % text)
    unit = norm_unit(m.group(2)) or field_unit or default_unit
    return parse_number(m.group(1), decimal) * UNIT_KG[unit]


def norm_form(f):
    f = re.sub(r"\s+", "", (f or "").strip()).upper()
    return {"ISO": "ISO", "YMD": "ISO", "YYYY-MM-DD": "ISO", "DMY": "DMY",
            "MDY": "MDY", "MM/DD/YYYY": "MDY", "DD/MM/YYYY": "DMY_SLASH",
            "DD.MM.YYYY": "DMY", "DD-MM-YYYY": "DMY", "SERIAL": "SERIAL",
            "YYYYMMDD": "YYYYMMDD", "YYYYDDD": "YYYYDDD"}.get(f, f)


def parse_date(s, form):
    s = s.strip()
    form = norm_form(form)
    if re.match(r"^\d{4}-\d{1,2}-\d{1,2}[T ]\d", s):
        return to_utc(s).date()
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})$", s)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    if re.match(r"^\d{4}-\d{1,2}-\d{1,2}$", s) or form == "ISO":
        y, mo, d = (int(x) for x in re.split(r"\D+", s))
        return dt.date(y, mo, d)
    if form == "SERIAL":
        return dt.date(1899, 12, 30) + dt.timedelta(days=int(float(s)))
    if form == "YYYYMMDD":
        return dt.date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    if form == "YYYYDDD":
        return dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:7]) - 1)
    parts = [int(x) for x in re.split(r"\D+", s) if x]
    if form in ("DMY", "DMY_SLASH"):
        return dt.date(parts[2], parts[1], parts[0])
    if form == "MDY":
        return dt.date(parts[2], parts[0], parts[1])
    raise ValueError("bad date %r (%s)" % (s, form))


def to_utc(s):
    d = dt.datetime.fromisoformat(s.strip().replace("Z", "+00:00").replace("z", "+00:00"))
    if d.tzinfo is not None:
        d = d.astimezone(dt.timezone.utc)
    return d


def ship_month(s, form="ISO"):
    if re.search(r"\d[T ]\d", s.strip()) and ":" in s:
        d = to_utc(s).date()
    else:
        d = parse_date(s, form)
    return "%04d-%02d" % (d.year, d.month)


def make_rec(num, kind, month, kg, status):
    return {"num": num, "kind": kind, "month": month, "kg": kg,
            "counted": norm_status(status) in COUNTED}


def kind_of(s):
    s = (s or "").strip().lower()
    if s.startswith("c") or s.startswith("a"):
        return "correction"
    if s.startswith("v"):
        return "void"
    return "new"


# ---------------------------------------------------------------- delimited
def split_records(text):
    """Yield ('comment', line) or ('row', text) with quoted fields kept whole."""
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i].rstrip("\r")
        i += 1
        if line.startswith("#"):
            yield "comment", line
            continue
        if line.strip() == "":
            continue
        buf = line
        while buf.count('"') % 2 == 1 and i < len(lines):
            buf += "\n" + lines[i].rstrip("\r")
            i += 1
        yield "row", buf


def parse_fields(buf, delim):
    if delim == ",":
        for r in csv.reader(io.StringIO(buf, newline=""), delimiter=","):
            return r
        return []
    return buf.split(delim)


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    cols = COLUMNS[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit = BASE_UNIT[depot]
    decimal = "," if depot == "west" else "."
    hdr = None
    recs = []
    for typ, item in split_records(text):
        if typ == "comment":
            m = re.search(r"seq\s*[:=]?\s*(\d+)", item, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            m = re.match(r"#\s*([A-Za-z][A-Za-z \-_]*?)\s*:\s*(.*?)\s*$", item)
            if m:
                name = re.sub(r"[\s_\-]+", " ", m.group(1).lower())
                val = m.group(2)
                if name in ("dates", "date", "date format", "date form"):
                    date_form = val
                elif name in ("unit", "weight unit", "weight units", "units"):
                    mu = re.match(r"\s*([A-Za-z]+)", val)
                    if mu and norm_unit(mu.group(1)) in UNIT_KG:
                        unit = norm_unit(mu.group(1))
                    low = val.lower()
                    if depot == "west" or "decimal" in low:
                        if "decimal point" in low or "decimal dot" in low:
                            decimal = "."
                        elif "decimal comma" in low:
                            decimal = ","
            continue
        row = parse_fields(item, delim)
        stripped = [f.strip() for f in row]
        if stripped and all(f in cols for f in stripped) and len(set(stripped)) == len(stripped):
            hdr = stripped
            continue
        if hdr is None:
            continue
        try:
            rec = row_to_record(depot, hdr, row, date_form, unit, decimal)
        except Exception as e:  # keep going on a damaged row
            print("warning: skipping row %r: %s" % (item[:80], e), file=sys.stderr)
            continue
        if rec:
            recs.append(rec)
    return seq, recs


def row_to_record(depot, hdr, row, date_form, unit, decimal):
    idcol = "ref" if "ref" in hdr else "id"
    wcol = next((h for h in hdr if re.match(r"^(gross|weight)(_(kg|g|lb|oz))?$", h)), None)
    field_unit = None
    if wcol and "_" in wcol:
        field_unit = wcol.split("_")[1]
    row_unit = None
    if len(row) == len(hdr) + 1 and wcol:
        wi = hdr.index(wcol)
        cand = [wi + 1] + list(range(len(row)))
        for ci in cand:
            if ci < len(row) and norm_unit(row[ci]) in UNIT_KG and ci != wi:
                row_unit = norm_unit(row[ci])
                del row[ci]
                break
        else:
            raise ValueError("unexpected field count")
    d = {h: (row[i].strip() if i < len(row) else "") for i, h in enumerate(hdr)}
    num = id_number(d.get(idcol, ""))
    if num is None:
        return None  # trailer or junk
    kcol = next((c for c in ("type", "kind", "t", "typ", "rec") if c in d), None)
    kind = kind_of(d.get(kcol, "")) if kcol else "new"
    if kind == "void":
        return {"num": num, "kind": "void"}
    status = d.get("status", d.get("state", ""))
    if depot == "harbor":
        status = HARBOR_STATES.get(status.upper(), status)
    shipped = d.get("shipped", d.get("date", ""))
    month = ship_month(shipped, date_form)
    kg = parse_weight(d[wcol], row_unit or unit, decimal, field_unit)
    return make_rec(num, kind, month, kg, status)


# ---------------------------------------------------------------- others
def parse_xml(text):
    text = re.sub(r"^<\?xml[^>]*\?>", "", text.lstrip("﻿"))
    root = ET.fromstring(text)
    seq = root.get("seq")
    seq = int(seq) if seq and seq.strip().isdigit() else None
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit") or "kg")
    recs = []
    for el in root.iter("shipment"):
        try:
            num = id_number(el.get("id", ""))
            if num is None:
                continue
            kind = kind_of(el.get("type", ""))
            if kind == "void":
                recs.append({"num": num, "kind": "void"})
                continue
            shipped = el.get("shipped")
            if shipped is None:
                shipped = (el.findtext("shipped") or "")
            w = el.find("weight")
            if w is not None:
                wtext, wunit = (w.text or ""), w.get("unit")
            else:
                wtext, wunit = el.get("weight", ""), el.get("unit")
            kg = parse_weight(wtext, root_unit, ".", norm_unit(wunit) if wunit else None)
            status = el.findtext("status") or el.get("status") or ""
            recs.append(make_rec(num, kind, ship_month(shipped), kg, status))
        except Exception as e:
            print("warning: skipping shipment %r: %s" % (el.get("id"), e), file=sys.stderr)
    return seq, recs


def parse_jsonl(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            val = json.loads(line)
        except ValueError:
            continue
        objs = val if isinstance(val, list) else [val]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and o["meta"].get("seq") is not None:
                    seq = int(o["meta"]["seq"])
                continue
            try:
                num = id_number(str(o.get("id", "")))
                if num is None:
                    continue
                kind = kind_of(o.get("kind", ""))
                if kind == "void":
                    recs.append({"num": num, "kind": "void"})
                    continue
                wk = next(k for k in o if k.lower().startswith("weight"))
                fu = wk.lower().split("_", 1)[1] if "_" in wk else None
                kg = parse_weight(str(o[wk]), "kg", ".", norm_unit(fu) if fu else None)
                recs.append(make_rec(num, kind, ship_month(o["shipped_at"]), kg, o.get("status", "")))
            except Exception as e:
                print("warning: skipping record %r: %s" % (o.get("id"), e), file=sys.stderr)
    return seq, recs


def parse_fixed(text):
    seq = None
    layout = "FW1"
    recs = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.startswith("#LAYOUT"):
            name = line.split()[1].upper() if len(line.split()) > 1 else layout
            if name in LAYOUTS:
                layout = name
            continue
        if line.startswith("#SEQ"):
            m = re.search(r"\d+", line)
            if m and seq is None:
                seq = int(m.group())
            continue
        if line.startswith("#"):
            continue
        line = line.replace("\x0c", "")
        if not line.strip() or "SHIPMENT LISTING" in line:
            continue
        use = layout
        if len(line) != LAYOUTS[layout][0]:
            match = [n for n, (ln, _) in LAYOUTS.items() if ln == len(line)]
            if not match:
                continue
            use = match[0]
        try:
            f = {k: line[a - 1:b] for k, (a, b) in LAYOUTS[use][1].items()}
            num = id_number(f["id"])
            if num is None:
                continue
            kind = kind_of(f["type"])
            if kind == "void":
                recs.append({"num": num, "kind": "void"})
                continue
            if use == "FW1" or use == "FW3":
                d = dt.date(int(f["shipped"][:4]), 1, 1) + dt.timedelta(days=int(f["shipped"][4:7]) - 1)
            else:
                d = dt.date(int(f["shipped"][:4]), int(f["shipped"][4:6]), int(f["shipped"][6:8]))
            n = int(f["weight"])
            if use == "FW1":
                kg = Decimal(n) * UNIT_KG["g"]
            elif use == "FW2":
                kg = Decimal(n) / 100
            else:
                kg = Decimal(n) / 10 * UNIT_KG["lb"]
            recs.append(make_rec(num, kind, "%04d-%02d" % (d.year, d.month), kg,
                                 FW_STATUS.get(f["status"].strip().upper(), f["status"])))
        except Exception as e:
            print("warning: skipping line %r: %s" % (line[:50], e), file=sys.stderr)
    return seq, recs


def parse_file(depot, path):
    text = decode(read_bytes(path))
    if depot == "central":
        return parse_xml(text)
    if depot == "north":
        return parse_jsonl(text)
    if depot == "south":
        return parse_fixed(text)
    if depot in DELIMS:
        return parse_delimited(depot, text)
    # unknown depot: sniff the family
    s = text.lstrip("﻿ \n")
    if s.startswith("<"):
        return parse_xml(text)
    if s.startswith("{") or s.startswith("["):
        return parse_jsonl(text)
    return None, []


# ---------------------------------------------------------------- main
def q2(x):
    return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN))


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split("-", 1)[0], []).append(p)

    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for p in paths:
            try:
                seq, recs = parse_file(depot, p)
            except Exception as e:
                print("warning: cannot read %s: %s" % (p, e), file=sys.stderr)
                continue
            exports.append((seq if seq is not None else -1, os.path.basename(p), recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                n = r["num"]
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    if n in cur:
                        del cur[n]
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(HANDOVER_ORDER)}
    owners = {}
    for depot in sorted(current, key=lambda d: (order.get(d, 99), d)):
        for n in current[depot]:
            owners.setdefault(n, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Decimal(0)] for d in files}
    months = {}
    for n, ds in owners.items():
        depot = ds[0]
        r = current[depot][n]
        if not r["counted"]:
            continue
        depots[depot][0] += 1
        depots[depot][1] += r["kg"]
        if r["month"]:
            m = months.setdefault(r["month"], [0, Decimal(0)])
            m[0] += 1
            m[1] += r["kg"]

    out = {
        "depots": {d: {"shipments": v[0], "total_kg": q2(v[1])} for d, v in sorted(depots.items())},
        "months": {m: {"shipments": v[0], "total_kg": q2(v[1])} for m, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
